<template><PageShell title="DSS & Operational Settings" subtitle="Adjust the thesis DSS weighting and lightweight operational timing controls without changing code." icon="lucide:brain-circuit" eyebrow="Platform Executive"><section class="max-w-4xl rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829] sm:p-6"><div v-if="loading" class="py-14 text-center text-sm text-slate-400">Loading settings...</div><template v-else><div class="grid gap-4 sm:grid-cols-2"><label v-for="key in weightKeys" :key="key" class="rounded-2xl bg-base-200 p-4"><span class="text-xs font-black uppercase text-slate-400">{{ pretty(key) }} weight</span><div class="mt-2 flex items-center gap-3"><input v-model.number="form.weights[key]" type="number" min="0" max="1" step="0.05" class="w-full rounded-xl border border-base-300 bg-base-100 px-3 py-2.5 text-sm font-black dark:bg-white/5 dark:text-white"/><span class="text-xs font-bold text-slate-400">{{ Math.round((form.weights[key]||0)*100) }}%</span></div></label></div><div class="mt-3 rounded-2xl border p-4" :class="Math.abs(weightTotal-1)<.001?'border-emerald-200 bg-emerald-50/70':'border-red-200 bg-red-50/70'"><p class="text-sm font-black">Weight total: {{ weightTotal.toFixed(2) }}</p><p class="mt-1 text-xs text-slate-500">The four factors must total exactly 1.00.</p></div><div class="mt-6 grid gap-4 sm:grid-cols-3"><Field label="Offer timeout (seconds)" v-model.number="form.offer_timeout_seconds"/><Field label="Active GPS interval" v-model.number="form.tracking_active_seconds"/><Field label="Idle GPS interval" v-model.number="form.tracking_idle_seconds"/></div><div class="mt-6 flex justify-end"><button class="rounded-xl bg-red-600 px-5 py-3 text-xs font-black text-white disabled:opacity-50" :disabled="saving||Math.abs(weightTotal-1)>.001" @click="save">{{ saving?'Saving...':'Save operational settings' }}</button></div></template></section></PageShell></template>
<script setup>import{computed,defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformDssSettings,savePlatformDssSettings}from'@/services/adminCompletion';import{useToast}from'@/composables/useToast';const toast=useToast(),loading=ref(false),saving=ref(false),weightKeys=['distance','availability','capability','workload'],form=ref({weights:{distance:.4,availability:.3,capability:.2,workload:.1},offer_timeout_seconds:90,tracking_active_seconds:15,tracking_idle_seconds:60});const weightTotal=computed(()=>weightKeys.reduce((n,k)=>n+Number(form.value.weights[k]||0),0));const pretty=v=>v[0].toUpperCase()+v.slice(1);const Field=defineComponent({props:{label:String,modelValue:Number},emits:['update:modelValue'],setup:(p,{emit})=>()=>h('label',{class:'block'},[h('span',{class:'mb-1.5 block text-xs font-black uppercase text-slate-400'},p.label),h('input',{class:'w-full rounded-xl border border-base-300 bg-base-100 px-3 py-2.5 text-sm font-bold dark:bg-white/5 dark:text-white',type:'number',value:p.modelValue,onInput:e=>emit('update:modelValue',Number(e.target.value))})])});async function load(){loading.value=true;try{const d=await fetchPlatformDssSettings(),s=d.settings||{};form.value.weights=s['dispatch.dss.weights']?.value||form.value.weights;form.value.offer_timeout_seconds=Number(s['dispatch.offer_timeout_seconds']?.value||90);const t=s['tracking.default_interval_seconds']?.value||{};form.value.tracking_active_seconds=Number(t.active||15);form.value.tracking_idle_seconds=Number(t.idle||60)}finally{loading.value=false}}async function save(){saving.value=true;try{const d=await savePlatformDssSettings(form.value);toast.success(d.message)}catch(e){toast.error(e?.response?.data?.message||'Unable to save settings.')}finally{saving.value=false}}onMounted(load)</script>
